shots.draw_js:
clearScene();setBig(null);setEq(null);
gridworld({rows:1,cols:4,cs:110,y:250,x:420,
  tag:function(i,j){return "帧"+(j+1);},
  cls:function(){return "b";}});
note("一帧看不出速度方向",640,400,"r");
note("所以取最近四帧",640,448,"y");
setCap("DQN 的状态不是一帧，是<b>最近四帧</b>。这是一个有理由的选择。");

clearScene();setEq(null);
setBig("四帧就是状态","够用了，剩下的是调参问题");
setCap("它在多数游戏上<b>够用</b> —— 但「够用」和「是状态」是两件事。");

clearScene();setBig(null);
setEq("$$P(s'\\mid s_t,a_t)=P(s'\\mid h_t,a_t)$$","top");
note("L1 第五集的判据",640,300,"y lg");
note("四帧之外的历史必须无关",640,360,"sm lg");
setCap("判据没变：<b>知道状态之后，再知道历史也不改变预测</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"Breakout",sub:"物理只看位置与速度",state:"on"},
  {label:"多数街机游戏",sub:"四帧近似够用",state:"on"},
  {label:"Montezuma",sub:"钥匙在几十步前",state:"dead"}]});
note("同一个状态定义，两种结果",640,420,"y");
setCap("同一套状态定义：多数游戏近似成立，<b>需要记忆的游戏直接失效</b>。");

clearScene();setBig(null);setEq(null);
note("够用",400,290,"g lg");
note("是充分统计量",880,290,"y lg");
note("两个不同的命题",640,400,"r lg");
setCap("<b>指名反驳</b>：四帧是一个<b>近似</b>的 Markov 统计量，而且它的失效点是已知的。");

clearScene();setBig(null);
setEq("$$\\Delta w=\\alpha\\big(r+\\gamma\\max_{a'}\\hat Q(s',a';w)-\\hat Q(s,a;w)\\big)\\nabla_w\\hat Q$$","top");
note("直接接上网络会怎样",640,310,"y lg");
setCap("把 L4 的 Q-learning 和 L6 的网络<b>直接拼起来</b>：这一行就是全部。");

clearScene();setEq(null);
setBig("把表换成网络就行","算法照旧，只是 Q 的存法变了");
setCap("这正是 L5 第一集那个错误模型 —— 而这里它有了<b>两个具体的后果</b>。");

clearScene();setBig(null);setEq(null);
note("样本高度相关",400,280,"r lg");
note("目标一直在动",880,280,"r lg");
note("两个都违反监督学习的前提",640,400,"y lg");
setCap("两个病理：<b>样本不 IID</b> 与 <b>目标非平稳</b>。两个都不是「存法」问题。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"样本不 IID",sub:"→ 经验回放",state:"on"},
  {label:"目标非平稳",sub:"→ 固定 Q 目标",state:"on"},
  {label:"函数逼近本身",sub:"→ 没有补丁",state:"dead"}]});
note("一一对应，不是调参",640,420,"y");
setCap("两个病理，两个补丁，<b>一一对应</b> —— 而第三条没有对应物。");

clearScene();setBig(null);setEq(null);
note("IID",400,290,"g lg");
note("标签固定",880,290,"g lg");
note("补丁在修这两个前提",640,400,"y lg");
setCap("<b>指名反驳</b>：不是「换个存法」，是<b>监督学习的两个前提同时被破坏了</b>。");

clearScene();setBig(null);setEq(null);
gridworld({rows:1,cols:5,cs:100,y:250,x:390,
  tag:function(i,j){return "t+"+j;},
  cls:function(){return "r";}});
note("连续五帧几乎一样",640,400,"r");
note("喂进去的是同一类画面",640,448,"sm");
setCap("在线学习时，相邻样本<b>几乎相同</b>，而且都来自同一段轨迹。");

clearScene();setEq(null);
setBig("回放是为了省数据","存下来多用几次，样本效率高");
setCap("样本效率确实提高了 —— 但那是<b>副产品</b>，不是它被发明的理由。");

clearScene();setBig(null);
setEq("$$\\mathcal{D}=\\{(s,a,r,s')\\}\\ \\ |\\mathcal{D}|\\approx 10^6 \\ \\longrightarrow\\ \\text{minibatch}$$","top");
note("缓冲约一百万条",640,300,"b lg");
note("训练时随机抽小批量",640,360,"g lg");
setCap("做法只有两句：<b>把转移存进大缓冲</b>，<b>训练时随机抽小批量</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"主要作用",sub:"打散时间相关性",state:"on"},
  {label:"副产品",sub:"每条转移重复使用",state:"on"},
  {label:"新代价",sub:"数据来自旧策略",state:"dead"}]});
note("它让算法更「离策略」了",640,420,"r");
setCap("回放<b>加重</b>了三要素里的第三条：缓冲里的数据来自<b>很旧的</b>策略。");

clearScene();setBig(null);setEq(null);
note("主要是去相关",400,290,"g lg");
note("省数据是顺带",880,290,"sm lg");
note("代价：更离策略",640,400,"r lg");
setCap("<b>指名反驳</b>：主要目的是<b>去相关</b>，而它的代价是让第三条三要素更重。");
